import{_ as t,o as a,c as o,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Ceph Developer Summit - NVMe oF gateway","description":"","frontmatter":{"title":"Ceph Developer Summit - NVMe oF gateway","date":"2025-09-11T00:00:00.000Z","updated":"2025-09-12T00:00:00.000Z","tags":["Ceph","NVMe-oF","Storage Optimization","Gateway Features","Ceph Performance"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Ceph_Developer_Summit_-_NVMe_oF_gateway.md","filePath":"posts/2025/Ceph_Developer_Summit_-_NVMe_oF_gateway.md","lastUpdated":1780459816000}'),r={name:"posts/2025/Ceph_Developer_Summit_-_NVMe_oF_gateway.md"};function l(n,e,s,_,h,c){return a(),o("div",null,[...e[0]||(e[0]=[i('<p>Ceph NVMe-oF 网关功能优化会议纪要</p><p>本次会议重点讨论了Ceph NVMe-oF网关的功能优化计划，包括故障转移时间缩短、Active-Active网关支持、自动化管理增强以及性能优化等多个议题。</p><h3 id="关键讨论内容" tabindex="-1">关键讨论内容 <a class="header-anchor" href="#关键讨论内容" aria-label="Permalink to &quot;关键讨论内容&quot;">​</a></h3><h4 id="_1-故障转移时间优化" tabindex="-1">1. 故障转移时间优化 <a class="header-anchor" href="#_1-故障转移时间优化" aria-label="Permalink to &quot;1. 故障转移时间优化&quot;">​</a></h4><ul><li><strong>当前问题</strong>：故障转移时间约为12秒，主要因等待10秒确认网关离线，且beacon频率为5秒（需错过2次beacon才触发）。</li><li><strong>改进方案</strong>：优化beacon机制，仅发送状态差异（delta），降低数据量以支持1秒/次的高频beacon。</li><li><strong>目标</strong>：故障转移时间目标缩短至5-7秒（可配置，依赖网络稳定性）。</li><li><strong>风险</strong>：网络不稳定时可能导致误判（需用户根据环境调整参数）。</li></ul><h4 id="_2-active-active-网关支持" tabindex="-1">2. Active-Active 网关支持 <a class="header-anchor" href="#_2-active-active-网关支持" aria-label="Permalink to &quot;2. Active-Active 网关支持&quot;">​</a></h4><ul><li><strong>当前限制</strong>：每个namespace仅由单一网关服务，多网关利用率低。</li><li><strong>目标</strong>：支持多网关同时写入（需解决IO顺序一致性问题）。</li><li><strong>挑战</strong>：数据损坏风险；需要开发重试/一致性逻辑；验证Initiator兼容性。</li></ul><h4 id="_3-自动化管理增强" tabindex="-1">3. 自动化管理增强 <a class="header-anchor" href="#_3-自动化管理增强" aria-label="Permalink to &quot;3. 自动化管理增强&quot;">​</a></h4><ul><li><strong>自动监听器（Auto Listeners）</strong>：用户无需手动为每个子系统配置监听器，网关将根据网络掩码（CIDR）自动匹配节点IP并创建监听器。</li><li><strong>元数据池（Metadata Pool）</strong>：首次部署网关时自动生成，无需用户手动创建。</li></ul><h4 id="_4-性能与功能优化" tabindex="-1">4. 性能与功能优化 <a class="header-anchor" href="#_4-性能与功能优化" aria-label="Permalink to &quot;4. 性能与功能优化&quot;">​</a></h4><ul><li><strong>批量创建 Namespace</strong>：支持单命令创建多个同名/同大小的namespace。</li><li><strong>SPDK 实时统计</strong>：新增CLI命令动态展示IOPS/延迟等指标。</li><li><strong>加密支持</strong>：讨论TLS（网关-Initiator）与RBD/OSD层加密的整合方案。</li><li><strong>负载均衡改进</strong>：未来引入实际负载（IOPS/吞吐量）均衡。</li></ul><h4 id="_5-其他计划" tabindex="-1">5. 其他计划 <a class="header-anchor" href="#_5-其他计划" aria-label="Permalink to &quot;5. 其他计划&quot;">​</a></h4><ul><li><strong>CSI Driver 支持</strong>：为Kubernetes提供NVMe-oF存储接口。</li><li><strong>Stretch Cluster 优化</strong>：故障转移时优先选择同站点网关。</li><li><strong>SOS 报告增强</strong>：完善NVMe相关日志收集。</li></ul><h3 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h3><ul><li>开发优先级：优先实现beacon优化和自动监听器。</li><li>测试验证：与多种Initiator进行兼容性测试，进行性能基准测试。</li><li>文档更新：新增配置参数说明。</li></ul><p>此次优化旨在显著提升Ceph NVMe-oF网关的可用性、性能和易用性，为未来多活架构奠定基础。</p>',16)])])}const g=t(r,[["render",l]]);export{u as __pageData,g as default};
